const DICT: Record<UiLanguage, Record<string, string>> = {
  en,
  hi: { ...hi, ...contentHi },
  bn: { ...bn, ...contentBn },
};

export function t(
  lang: UiLanguage,
  key: string,
  values: Record<string, string | number> = {},
): string {
  const fallback = en[key] ?? key;
  const translated = lang === "en" ? fallback : DICT[lang]?.[key] ?? DICT[lang]?.[fallback] ?? fallback;
  return translated.replace(/\{(\w+)\}/g, (token, name: string) =>
    Object.prototype.hasOwnProperty.call(values, name) ? String(values[name]) : token,
  );
}

export function localeForLanguage(lang: UiLanguage): string {
  return lang === "hi" ? "hi-IN" : lang === "bn" ? "bn-IN" : "en-IN";
}

export function formatDate(date: Date | string | number, lang: UiLanguage, options?: Intl.DateTimeFormatOptions): string {
  return new Intl.DateTimeFormat(localeForLanguage(lang), options).format(new Date(date));
}

export function formatNumber(value: number, lang: UiLanguage): string {
  return new Intl.NumberFormat(localeForLanguage(lang)).format(value);
}

